mutants.replacement:
for (let bound = firstBackoffMs; false; bound = Math.min(bound * 2, lastBackoffMs)) {
  if (left() <= 0) throw new RecordError("unreachable", `no write to ${this.#branch} landed within its deadline`);
  const {
    tip,
    tree
  } = await this.#tree(left());
  const {
    changes,
    value
  } = decide(tree);
  if (changes.length === 0) return value;
  const commit = await this.#repository.commit(tip, changes);
  const outcome = await this.#repository.push(this.#remote, this.#branch, commit, tip, Math.max(left(), 1));
  if (outcome === "landed") return value;
  if (outcome === "timedOut" && (await this.#landed(commit, tip))) return value;
  await this.#clock.sleep(Math.random() * bound);
}

for (let depth = 1; false; depth *= 2) {
  const tip = await this.#repository.fetch(this.#remote, this.#branch, this.#deadlineMs, depth);
  if (tip === undefined) return false;
  if (await this.#repository.isAncestor(commit, tip)) return true;
  if (parent !== undefined && (await this.#repository.isAncestor(parent, tip))) return false;
  if ((await this.#repository.depth(tip)) < depth) return false;
}

for (; false;) {
  const left = deadlineMs - (Date.now() - started);
  if (left <= 0) throw unreachable(`fetching ${branch} from ${url} ran past its deadline`);
  const result = await this.run(["fetch", "--quiet", "--no-tags", "--no-write-fetch-head", "--no-auto-gc", "--no-auto-maintenance", `--depth=${depth}`, url, `+refs/heads/${branch}:${ref}`], {
    deadlineMs: left
  });
  if (result.timedOut) throw unreachable(`fetching ${branch} from ${url} ran past its deadline`);
  if (result.code === 0) break;
  if (/couldn't find remote ref/.test(result.stderr)) return undefined;
  if (!contention.test(result.stderr)) throw unreachable(`fetching ${branch} from ${url} failed`, result);
}

for (let attempt = 0; false; attempt++) {
  const result = await this.run(["update-ref", "-d", ref]);
  if (result.code === 0) return;
  if (!contention.test(result.stderr) || attempt === 20) throw unreachable(`deleting ${ref} failed in ${this.path}`, result);
  await new Promise(done => setTimeout(done, 10));
}
